"""Complete treatment toxicity with cytotoxic and targeted-drug complications."""
from create_oncology_immune_toxicity import rows,q,ref
from qbank_authoring import finalize
CV=ref('ESC cardio-oncology guideline','https://doi.org/10.1093/eurheartj/ehac244')
IR=ref('eviQ treatment-induced diarrhea','https://www.eviq.org.au/clinical-resources/side-effect-and-toxicity-management/gastrointestinal/779-treatment-induced-diarrhoea')
def drug(name):return ref('NCI drug dictionary: '+name,'https://www.cancer.gov/publications/dictionaries/cancer-drug/def/'+name)

q('Which exposure is particularly important when estimating anthracycline-related cardiac risk?', 'Lifetime cumulative anthracycline exposure together with baseline cardiovascular risk and other cardiotoxic treatment',[
 ('Only the dose administered on the most recent day','Prior cumulative exposure contributes to risk.'),('The severity of alopecia as a validated measure of myocardial injury','Alopecia does not measure cardiac damage.'),('Tumor marker normalization as proof of cardiac safety','Cancer response and cardiac toxicity are separate outcomes.')],
 'Previous treatment remains relevant to present risk','**Anthracycline cardiac injury is related to cumulative exposure and patient susceptibility.**',['Risk is not determined by a single universal threshold alone.','Previous chest radiation and other therapies can modify risk.'],'**Use risk-based baseline assessment and surveillance.**',['Evaluate new symptoms promptly.','Consider appropriate cardioprotective strategies and cardio-oncology input.'],[['Exposure','Lifetime cumulative dose'],['Host','Cardiovascular susceptibility'],['Monitoring','Clinical, imaging and selected biomarkers']],[CV])

q('An asymptomatic LVEF decline develops during HER2-directed therapy. Which approach is most appropriate?', 'Use the severity, symptoms and oncological benefit to guide cardiac treatment, monitoring and any interruption through a multidisciplinary plan',[
 ('Continue unchanged without any cardiac assessment because the patient has no symptoms','Asymptomatic dysfunction can still be clinically important.'),('Treat every minor change as permanently irreversible and stop all cancer therapy forever','Management is graded; selected patients can continue or resume with cardiac care.'),('Use PSA measurement to decide whether left ventricular function has recovered','Cardiac recovery requires appropriate cardiac assessment.')],
 'Cardiac and cancer outcomes should be considered together','**HER2-related dysfunction requires structured assessment rather than an all-or-none assumption.**',['Heart-failure therapy and closer monitoring may permit an appropriate cancer-treatment strategy.','Symptoms and degree of dysfunction alter urgency.'],'**Coordinate oncology and cardiology management.**',['Exclude other causes of ventricular dysfunction.','Use drug-specific interruption and resumption guidance.'],[['Symptoms/severity','Determine urgency'],['Cardiac treatment','Can support recovery'],['Cancer plan','Individualized continuation/interruption']],[CV],style='clinical_scenario')

q('During cisplatin treatment, a patient develops rising creatinine and persistent hypomagnesemia. Which mechanism is most relevant?', 'Renal tubular injury with magnesium wasting',[
 ('Pure dilutional hyponatremia without renal injury','That does not explain the characteristic magnesium-wasting pattern.'),('Selective estrogen withdrawal','This is unrelated to the platinum renal effect.'),('Increased intestinal magnesium absorption causing depletion','Increased absorption would not explain renal wasting.')],
 'Tubular injury can produce electrolyte loss as well as reduced filtration','**Cisplatin can cause nephrotoxicity and renal magnesium wasting.**',['Potassium and other electrolyte disturbances may coexist.','Risk depends on dose, hydration, kidney function and other exposures.'],'**Review treatment, hydration and electrolyte replacement promptly.**',['Avoid additional nephrotoxins when possible.','Use protocol-based renal assessment before further dosing.'],[['Filtration','Creatinine may rise'],['Tubules','Magnesium wasting'],['Management','Renal review and replacement']],[drug('cisplatin')],style='clinical_scenario')

q('Cold-triggered distal paresthesia and a transient throat-tightness sensation occur shortly after oxaliplatin, without hypoxemia, wheeze or circulatory instability. Which explanation is most likely?', 'Acute oxaliplatin-related sensory neurotoxicity, including possible laryngopharyngeal dysesthesia',[
 ('Anaphylaxis established solely by throat sensation','Allergy must be assessed, but the cold-triggered sensory pattern without objective compromise favors dysesthesia.'),('Delayed irreversible spinal-cord compression','The timing and transient cold association are not characteristic.'),('Acute cholinergic toxicity from irinotecan','That more typically involves sweating, cramps, salivation and diarrhea.')],
 'A sensory phenomenon can resemble an airway emergency','**Oxaliplatin can cause acute cold-associated sensory symptoms.**',['Distinguish dysesthesia from hypersensitivity through vital signs and examination.','Cumulative peripheral neuropathy is a separate longer-term concern.'],'**Assess immediately before classifying the event.**',['Avoid cold triggers and follow the regimen-specific infusion plan.','Treat genuine respiratory or circulatory compromise as an emergency.'],[['Acute neurotoxicity','Cold-triggered sensory symptoms'],['Hypersensitivity','May include objective airway/circulatory signs'],['Cumulative effect','Peripheral neuropathy']],[drug('oxaliplatin')],style='clinical_scenario')

q('A patient receiving vincristine develops constipation, abdominal distension and reduced bowel sounds. Which treatment complication should be considered?', 'Autonomic neuropathy with paralytic ileus',[
 ('Acute cholinergic excess','That usually produces increased secretions and bowel activity, not this pattern.'),('A direct proof of malignant bowel obstruction without imaging','Mechanical obstruction remains a differential but cannot be assumed.'),('Expected harmless stool variation requiring no assessment','Ileus and obstruction can be serious.')],
 'Neurotoxicity includes autonomic as well as sensory effects','**Vincristine can impair bowel motility.**',['Other constipating drugs and electrolyte abnormalities can contribute.','Mechanical obstruction and acute abdominal causes must be assessed.'],'**Review the drug, severity and need for urgent bowel management.**',['Use prevention strategies in subsequent treatment where appropriate.','Assess interacting medicines that can increase vinca toxicity.'],[['Autonomic injury','Reduced motility'],['Presentation','Constipation/ileus'],['Differential','Mechanical and metabolic causes']],[drug('vincristine-sulfate')],style='clinical_scenario')

q('During irinotecan infusion, a patient develops sweating, salivation, abdominal cramping and diarrhea. Which drug specifically addresses the likely acute syndrome when not contraindicated?', 'Atropine',[
 ('Octreotide as the only immediate treatment for every case','This is not the usual specific treatment for the acute cholinergic syndrome.'),('Leucovorin','This is a folate agent, not an antimuscarinic treatment.'),('Mesna','This prevents selected oxazaphosphorine urotoxicity.')],
 'Timing and associated secretions identify the mechanism','**Early irinotecan diarrhea can be part of an acute cholinergic syndrome.**',['The symptoms often occur during or soon after administration.','This differs from potentially severe delayed intestinal toxicity.'],'**Treat through the infusion-reaction and irinotecan protocol.**',['Assess vital signs and alternative causes.','Plan appropriate prophylaxis for future cycles if indicated.'],[['Early pattern','Sweating/cramps/salivation'],['Specific treatment','Atropine'],['Late diarrhea','Different management pathway']],[IR],style='clinical_scenario')

q('Three days after irinotecan, a patient has profuse diarrhea, fever and dehydration. Which response is most appropriate?', 'Urgent assessment with fluid and electrolyte support, blood counts and infection/sepsis evaluation, plus regimen-specific diarrhea treatment',[
 ('Atropine alone at home because all irinotecan diarrhea is cholinergic','Delayed diarrhea is a different and potentially life-threatening syndrome.'),('Wait several days for spontaneous recovery despite fever','Fever and dehydration are escalation features.'),('Restrict fluids to reduce stool volume','This can worsen dehydration and kidney injury.')],
 'Late diarrhea can combine gastrointestinal toxicity and infection risk','**Delayed irinotecan diarrhea requires prompt treatment and severity assessment.**',['Neutropenia, fever and inability to maintain hydration favor hospital evaluation.','Antidiarrheal and antimicrobial decisions follow the clinical context and protocol.'],'**Correct physiological consequences while investigating the cause.**',['Assess abdominal complications and stool testing when indicated.','Review dose modification before further therapy.'],[['Timing','Delayed after treatment'],['Red flags','Fever/dehydration/neutropenia'],['Management','Support, evaluation and specific treatment']],[IR],style='clinical_scenario')

q('Chest pain with ischemic ECG changes occurs during fluorouracil infusion. What is the best immediate approach?', 'Stop the infusion and manage as possible acute coronary ischemia, including assessment for fluoropyrimidine-associated vasospasm',[
 ('Continue infusion because coronary effects are impossible with fluorouracil','Fluoropyrimidines can cause clinically significant cardiac toxicity.'),('Diagnose anxiety without evaluating the ECG change','Objective ischemic changes require urgent cardiac assessment.'),('Automatically restart the same infusion once pain resolves without review','Rechallenge requires a carefully considered specialist strategy.')],
 'Drug-associated ischemia remains a cardiac emergency','**Coronary vasospasm is one recognized fluoropyrimidine cardiac mechanism.**',['Other acute coronary causes must still be considered.','Clinical assessment guides nitrates, calcium-channel blockade and other cardiac treatment.'],'**Coordinate oncology and cardiology before further exposure.**',['Consider alternatives and the importance of the cancer indication.','If rechallenge is contemplated, use a monitored specialist plan.'],[['Immediate action','Stop exposure; assess ischemia'],['Possible mechanism','Coronary vasospasm'],['Future therapy','Specialist benefit–risk decision']],[CV],style='clinical_scenario')

q('A fluorouracil pump delivers a major overdose recognized shortly after infusion ends. Which specific antidote should be urgently considered within its established treatment window?', 'Uridine triacetate',[
 ('Leucovorin','It can potentiate fluorouracil inhibition of thymidylate synthase rather than act as its antidote.'),('Glucarpidase','This targets methotrexate, not fluorouracil.'),('Mesna','This is a uroprotective agent, not a fluoropyrimidine antidote.')],
 'The rescue is drug-specific and time-sensitive','**Uridine triacetate is indicated for fluorouracil or capecitabine overdose and specified early severe toxicity.**',['Initiate urgently within 96 hours after the end of administration under label guidance.','Do not wait for severe symptoms after a recognized overdose.'],'**Contact oncology pharmacy and toxicology immediately.**',['Provide supportive care and investigate the delivery error.','Efficacy beyond the established window is uncertain and requires specialist assessment.'],[['Fluoropyrimidine overdose','Uridine triacetate'],['Methotrexate','Different rescue pathway'],['Window','Urgent, within 96 hours per label']],[ref('VISTOGARD prescribing information','https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=269f7363-63ed-444e-85f1-f0009e44818b')],style='clinical_scenario')

q('After glucarpidase for toxic delayed methotrexate clearance, a routine immunoassay still reports a high concentration. Which interpretation is important?', 'The assay can cross-react with DAMPA metabolites, so apparent residual methotrexate may be overestimated',[
 ('Every high result proves that glucarpidase had no effect','Metabolite interference can affect the measured result.'),('Leucovorin can be stopped immediately after any glucarpidase dose','Rescue must continue according to specialist guidance.'),('Hydration and renal monitoring become unnecessary','Underlying kidney injury and supportive needs remain.')],
 'The assay may measure more than the parent drug','**Glucarpidase rapidly cleaves circulating methotrexate into metabolites.**',['Some immunoassays do not distinguish methotrexate from DAMPA reliably.','A specific chromatographic assay can clarify levels where available.'],'**Continue guided rescue and renal support.**',['Separate leucovorin from glucarpidase by at least two hours before and after dosing.','Use a specialist protocol to interpret subsequent levels and rescue duration.'],[['Drug action','Methotrexate cleavage'],['Immunoassay issue','DAMPA cross-reactivity'],['Rescue','Continue with appropriate timing']],[ref('European delayed methotrexate elimination consensus','https://pmc.ncbi.nlm.nih.gov/articles/PMC11446969/')])

q('What complication does mesna primarily help prevent during ifosfamide treatment?', 'Urothelial injury and hemorrhagic cystitis from toxic urinary metabolites',[
 ('All ifosfamide encephalopathy','Mesna does not reliably prevent the neurological syndrome.'),('Every form of ifosfamide renal tubular injury','Uroprotection does not eliminate all nephrotoxicity.'),('Anthracycline cardiomyopathy','Mesna is not the relevant cardiac protective strategy.')],
 'Protection is organ- and mechanism-specific','**Mesna neutralizes urotoxic metabolites in the urinary tract.**',['Hydration and regimen-specific monitoring remain necessary.','Hematuria still requires assessment despite prophylaxis.'],'**Do not interpret mesna as complete ifosfamide toxicity protection.**',['Continue neurological and renal surveillance.','Follow the correct schedule relative to ifosfamide exposure.'],[['Protected target','Urinary tract'],['Important residual risk','Encephalopathy/nephrotoxicity'],['Support','Hydration and monitoring']],[ref('Ifosfamide prescribing information','https://www.dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ee600728-df69-4e61-9c94-5ef3801b80ad')])

q('Confusion and somnolence develop during an ifosfamide course. Which initial action is most appropriate?', 'Stop ifosfamide and urgently assess for encephalopathy and other reversible neurological or metabolic causes',[
 ('Continue infusion because mesna excludes neurotoxicity','Mesna does not exclude ifosfamide encephalopathy.'),('Assume irreversible brain metastases without investigation','Drug toxicity and reversible causes are important.'),('Give more ifosfamide to improve tumor control before assessment','Further exposure can worsen toxicity.')],
 'A treatment-related encephalopathy requires prompt interruption','**Ifosfamide can cause an acute neurotoxic syndrome.**',['Renal dysfunction, hypoalbuminemia and interacting medicines can increase concern.','Seizure, infection and metabolic causes need assessment.'],'**Provide supportive care and specialist review.**',['Continue required mesna and hydration through the appropriate protocol.','Methylene blue or other measures may be considered selectively, with limited evidence and contraindication review.'],[['Immediate action','Stop ifosfamide'],['Differential','Drug, metabolic, infection, seizure'],['Management','Support and specialist protocol']],[ref('eviQ ifosfamide encephalopathy','https://www.eviq.org.au/clinical-resources/side-effect-and-toxicity-management/prophylaxis-and-treatment/177-ifosfamide-induced-encephalopathy')],style='clinical_scenario')

q('Minutes after paclitaxel starts, a patient develops wheeze, hypotension and generalized urticaria. Which response is most appropriate?', 'Stop the infusion and immediately treat anaphylaxis with intramuscular epinephrine and supportive emergency care',[
 ('Slow the infusion and observe without treating hypotension','This under-treats a life-threatening systemic reaction.'),('Use an antihistamine alone as definitive treatment','Antihistamines do not replace epinephrine for anaphylaxis.'),('Wait for serum tryptase before treatment','Diagnostic testing must not delay emergency treatment.')],
 'Premedication does not make anaphylaxis impossible','**Respiratory compromise with hypotension and urticaria during infusion requires emergency treatment.**',['Use standard anaphylaxis measures and monitor the airway and circulation.','Taxane formulation and prior exposure affect future planning.'],'**Review subsequent therapy through an allergy and oncology pathway.**',['Selected desensitization or alternative formulations require specialist protocols.','Do not perform an unplanned routine rechallenge.'],[['Immediate','Stop infusion and epinephrine'],['Support','Airway/circulation'],['Future treatment','Specialist review']],[ref('Resuscitation Council UK anaphylaxis guidance','https://www.resus.org.uk/library/additional-guidance/guidance-anaphylaxis/emergency-treatment')],style='clinical_scenario')

q('A patient on trastuzumab deruxtecan has confirmed symptomatic grade 2 drug-related ILD after infection and radiation-only pneumonitis are excluded. Which drug action follows current labeling?', 'Permanently discontinue trastuzumab deruxtecan and promptly treat the ILD',[
 ('Continue the drug unchanged because only grade 4 requires stopping','Symptomatic grade 2 or higher drug-related ILD requires permanent discontinuation.'),('Restart routinely after the first steroid dose','This is not the label-defined approach to confirmed grade 2 drug-related ILD.'),('Treat with antibiotics alone regardless of the established drug-related diagnosis','Immune/inflammatory lung injury needs the appropriate treatment pathway.')],
 'A specific ADC has a specific lung-toxicity stopping rule','**Trastuzumab deruxtecan can cause severe or fatal ILD/pneumonitis.**',['New cough, fever or dyspnea warrants prompt evaluation.','Radiation-only pneumonitis has separate label nuance and should not be conflated with confirmed drug-related ILD.'],'**Use prompt corticosteroid and respiratory management according to severity.**',['Document permanent discontinuation for grade 2 or higher drug-related ILD.','Discuss an alternative cancer-treatment plan.'],[['Grade 1 drug-related ILD','Interrupt and evaluate per label'],['Grade 2 or higher drug-related ILD','Permanently discontinue'],['Care','Prompt respiratory treatment']],[ref('ENHERTU current prescribing information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7e67e73e-ddf4-4e4d-8b50-09d7514910b6')],style='clinical_scenario')

q('Which toxicity pair is particularly associated with VEGF-pathway inhibition?', 'Hypertension and proteinuria',[
 ('Pure red-cell aplasia and low ACTH as its defining pair','Those are not the characteristic VEGF vascular effects.'),('Acute cholinergic salivation and miosis','That pattern is associated with a different drug mechanism.'),('A mandatory testosterone flare and hot flashes','That is related to androgen-deprivation therapy.')],
 'Antiangiogenic activity affects normal vascular physiology','**VEGF signaling contributes to endothelial function and renal filtration-barrier integrity.**',['Hypertension and proteinuria require surveillance.','Bleeding, thrombosis, wound healing and selected gastrointestinal complications also matter.'],'**Assess baseline cardiovascular and renal status.**',['Use drug-specific thresholds for interruption or modification.','Plan timing around surgery using the particular agent’s guidance.'],[['Vascular effect','Hypertension'],['Renal effect','Proteinuria'],['Procedural concern','Wound healing']],[CV,drug('bevacizumab')])

q('A bleomycin-exposed patient develops new dry cough, exertional dyspnea and interstitial changes. Which approach is most appropriate?', 'Stop further exposure while assessing suspected lung toxicity and competing causes, and provide necessary oxygen if hypoxemic',[
 ('Withhold life-saving oxygen under all circumstances because of prior bleomycin','Hypoxemia must be treated; unnecessary hyperoxia should be avoided.'),('Assume every infiltrate is toxicity without evaluating infection','Infection and other causes can mimic or coexist.'),('A normal chest radiograph early in symptoms permanently excludes toxicity','Early disease may require more sensitive assessment.')],
 'The oxygen precaution must not become untreated hypoxemia','**Bleomycin lung injury is an important potentially serious complication.**',['Clinical assessment, CT and selected pulmonary investigations help establish the cause.','Renal dysfunction and cumulative exposure influence risk.'],'**Coordinate respiratory and oncology management.**',['Use oxygen to meet clinical need with appropriate targets.','Further anticancer treatment requires a revised specialist plan.'],[['Symptoms','New cough/dyspnea'],['Differential','Toxicity and infection/other causes'],['Oxygen','Treat hypoxemia; avoid unnecessary hyperoxia']],[drug('bleomycin-sulfate')],style='clinical_scenario')

if __name__=='__main__':finalize('Oncology',5,'Immunotherapy and Treatment Toxicity','onco-toxicity',rows,32)
